package com.digitalhealth.controller;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import jakarta.validation.ConstraintViolationException; import org.springframework.web.bind.MethodArgumentNotValidException; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(ResponseStatusException.class) ResponseEntity<Map<String,String>> status(ResponseStatusException e){return ResponseEntity.status(e.getStatusCode()).body(Map.of("message",e.getReason()==null?"Request failed":e.getReason()));} @ExceptionHandler({MethodArgumentNotValidException.class,ConstraintViolationException.class}) ResponseEntity<Map<String,String>> validation(Exception e){return ResponseEntity.badRequest().body(Map.of("message","Please correct the highlighted information."));} @ExceptionHandler(Exception.class) ResponseEntity<Map<String,String>> unknown(Exception e){return ResponseEntity.status(500).body(Map.of("message","An unexpected error occurred."));} }
